int main() {
    int n; if (!(cin >> n)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    if (n <= 2) { cout << "Yes\n"; return 0; }
    long long diff = a[1] - a[0]; bool ok = true;
    for (int i = 1; i < n - 1; i++) if (a[i + 1] - a[i] != diff) { ok = false; break; }
    cout << (ok ? "Yes" : "No") << "\n";
    return 0;
}

