const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const arr = toks.slice(1, n + 1).map(x => BigInt(x));
    arr.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    if (n <= 2) { console.log("Yes"); return; }
    const diff = arr[1] - arr[0];
    let ok = true;
    for (let i = 1; i < n - 1; i++) if (arr[i + 1] - arr[i] !== diff) { ok = false; break; }
    console.log(ok ? "Yes" : "No");
}
main();

